import React from 'react';

export function Logo({ variant = 'horizontal', className = '' }: { variant?: 'horizontal' | 'icon', className?: string }) {
  if (variant === 'icon') {
    return (
      <svg className={`${className}`} width="32" height="32" viewBox="0 0 32 32" aria-hidden="true">
        <image href={`data:image/png;base64,`} x="0" y="0" width="140" height="32" preserveAspectRatio="xMinYMid slice" />
      </svg>
    );
  }
  return (
    <svg className={`${className} h-[32px] md:h-[36px] w-auto`} viewBox="0 0 140 32" aria-hidden="true" style={{ minWidth: '100px' }}>
      <image href={`data:image/png;base64,`} x="0" y="0" width="100%" height="100%" preserveAspectRatio="xMinYMid meet" />
    </svg>
  );
}
